import sys

def find_min_atoms(n, sets):
    from itertools import combinations

    def is_atom(atom, sets):
        for s in sets:
            if not (set(atom).issubset(s) or set(atom).isdisjoint(s)):
                return False
        return True

    elements = list(range(n))
    min_atoms = n

    for r in range(1, n + 1):
        for atom_combination in combinations(elements, r):
            if is_atom(atom_combination, sets):
                remaining_elements = [e for e in elements if e not in atom_combination]
                if not remaining_elements:
                    return 1
                else:
                    remaining_sets = [s for s in sets if not set(atom_combination).issubset(s)]
                    min_atoms = min(min_atoms, 1 + find_min_atoms(len(remaining_elements), remaining_sets))

    return min_atoms

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        m = int(input[index + 1])
        index += 2
        sets = []
        for _ in range(m):
            v_i = int(input[index])
            s_i = list(map(int, input[index + 1:index + 1 + v_i]))
            sets.append(s_i)
            index += 1 + v_i
        results.append(find_min_atoms(n, sets))
    for result in results:
        print(result)

main()
